import{fileURLToPath}from'node:url';import assert from 'node:assert/strict';import{writeFile}from'node:fs/promises';const{chromium}=await import(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');
const out=fileURLToPath(new URL('../../docs/qa/product-2026-11-17',import.meta.url));const b=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--mute-audio']});const results=[];
try{const p=await b.newPage({viewport:{width:700,height:1200}});for(const layout of['original','balanced','oval','classic']){await p.goto('http://127.0.0.1:5173/tests/fixtures/layout-audit.html?'+new URLSearchParams({layout,scene:'chat',width:390,height:844}),{waitUntil:'domcontentloaded'});await p.locator('#audit-stage[data-ready=true]').waitFor();await p.locator('.mx-chat-input').fill('离线键盘边界测试');for(const h of[650,500,1200]){await p.evaluate(h=>{Object.defineProperty(window.visualViewport,'height',{configurable:true,get:()=>h});window.visualViewport.dispatchEvent(new Event('resize'));},h);const r=await p.locator('.mx-chat-input').boundingBox();assert.ok(r.y+r.height<=h+1,`${layout} keyboard ${h}: composer occluded`);assert.equal(await p.locator('.mx-chat-input').inputValue(),'离线键盘边界测试');results.push({layout,visibleHeight:h,bottom:r.y+r.height,result:'pass'});}await p.locator('#audit-stage').screenshot({path:`${out}/${layout}-keyboard-restored.png`});}}finally{await b.close();await writeFile(out+'/keyboard-simulation.json',JSON.stringify(results,null,2));}console.log(results.length+' viewport keyboard checks');
